<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\EducationRecord; use Illuminate\Http\Request;
class EducationController extends Controller { public function index(){return view('admin.education.index',['records'=>EducationRecord::with('child')->latest()->paginate(20)]);} public function store(Request $r){$d=$r->validate(['child_id'=>'required|exists:children,id','school'=>'nullable|max:180','grade'=>'nullable|max:80','academic_year'=>'nullable|max:30','school_fees'=>'nullable|numeric|min:0','attendance'=>'nullable|numeric|min:0|max:100','results'=>'nullable','achievements'=>'nullable']);EducationRecord::create($d);return back()->with('success','Education record saved.');} public function update(Request $r,EducationRecord $record){$d=$r->validate(['school'=>'nullable|max:180','grade'=>'nullable|max:80','academic_year'=>'nullable|max:30','school_fees'=>'nullable|numeric|min:0','attendance'=>'nullable|numeric|min:0|max:100','results'=>'nullable','achievements'=>'nullable']);$record->update($d);return back()->with('success','Education record updated.');} public function destroy(EducationRecord $record){$record->delete();return back()->with('success','Education record removed.');} }
